sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float amount;
uniform float radius;
half4 main(float2 coord)
{
    half4 c = image.eval(coord);
    if (c.a <= 0.001) return half4(0.0);
    half3 col = c.rgb / c.a;

    float2 r = float2(radius, radius);
    half3 acc = half3(0.0);
    acc += (image.eval(coord - float2(r.x, r.y)).rgb / max(image.eval(coord - float2(r.x, r.y)).a, 0.001));
    acc += (image.eval(coord - float2(0.0, r.y)).rgb / max(image.eval(coord - float2(0.0, r.y)).a, 0.001));
    acc += (image.eval(coord - float2(r.x, 0.0)).rgb / max(image.eval(coord - float2(r.x, 0.0)).a, 0.001));
    acc += (image.eval(coord - float2(r.x, -r.y)).rgb / max(image.eval(coord - float2(r.x, -r.y)).a, 0.001));
    acc += (image.eval(coord + float2(0.0, r.y)).rgb / max(image.eval(coord + float2(0.0, r.y)).a, 0.001));
    acc += (image.eval(coord - float2(-r.x, r.y)).rgb / max(image.eval(coord - float2(-r.x, r.y)).a, 0.001));
    acc += (image.eval(coord + float2(0.0, -r.y)).rgb / max(image.eval(coord + float2(0.0, -r.y)).a, 0.001));
    acc += (image.eval(coord - float2(-r.x, -r.y)).rgb / max(image.eval(coord - float2(-r.x, -r.y)).a, 0.001));
    acc += (image.eval(coord - float2(-r.x, 0.0)).rgb / max(image.eval(coord - float2(-r.x, 0.0)).a, 0.001));

    half3 avg = acc / 8.0;

    half3 sharpened = col + amount * (col - avg);

    sharpened = clamp(sharpened, 0.0, 1.0);
    return half4(sharpened * c.a, c.a);
}
